WITH base AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, DATE_FORMAT(reading_ts, 'yyyy-MM') reading_ts_label FROM device_readings WHERE device_code IN ('DV-01', 'DV-04')), deduped AS (SELECT id, device_code, humidity FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY status_bits ASC, id ASC) AS rank_in_group FROM base) t WHERE rank_in_group = 1), metrics AS (SELECT id, humidity, SUM(humidity) OVER w_grp last3_sum_humidity, MIN(humidity) OVER w_grp last3_min_humidity, MAX(humidity) OVER w_grp last3_max_humidity, AVG(humidity) OVER w_grp last3_avg_humidity, LEAD(humidity, 2) OVER w_recent next_humidity FROM deduped WINDOW w_grp AS (PARTITION BY device_code ORDER BY humidity ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_recent AS (PARTITION BY device_code ORDER BY humidity ASC, id ASC)), cleaned AS (SELECT *, ROUND(next_humidity * 100, 2) adjusted_next_humidity, ROUND(last3_min_humidity, 0) last3_min_humidity_rounded FROM metrics WHERE last3_sum_humidity >= 160) SELECT CASE WHEN adjusted_next_humidity >= 66 THEN 'LARGE' ELSE 'SMALL' END AS adjusted_next_humidity_tier, CASE WHEN last3_max_humidity >= 65 THEN 'PREMIUM' ELSE 'STANDARD' END AS last3_max_humidity_tier, CASE WHEN last3_min_humidity_rounded >= 77 THEN 'PREMIUM' ELSE 'STANDARD' END AS last3_min_humidity_rounded_tier, PERCENTILE_APPROX(last3_max_humidity, ARRAY(0.25, 0.5, 0.75)) AS last3_max_humidity_quartiles, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(last3_min_humidity), 2) AS avg_last3_min_humidity, ROUND(AVG(humidity), 2) AS avg_humidity, COUNT(DISTINCT id) AS distinct_ids_2, PERCENTILE_APPROX(adjusted_next_humidity, 0.9) AS adjusted_next_humidity_p90 FROM cleaned GROUP BY CASE WHEN adjusted_next_humidity >= 66 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN last3_max_humidity >= 65 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN last3_min_humidity_rounded >= 77 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY avg_last3_min_humidity ASC NULLS LAST
